// Generated by scripts/generate_ascii_portrait.py from assets/source/portrait.png.
// Two ink directions: dark uses bright=dense, light uses dark=dense.
import darkRaw from './portrait-dark.txt?raw';
import lightRaw from './portrait-light.txt?raw';

export const asciiPortraits = {
  dark: darkRaw.replace(/\n$/, ''),
  light: lightRaw.replace(/\n$/, ''),
};

// Backwards-compatible alias.
export const asciiPortrait = asciiPortraits.dark;

const lines = asciiPortraits.dark.split('\n');

export const asciiSize = {
  cols: lines[0].length,
  rows: lines.length,
};
